import{_ as n,o as e,c as s,ai as t}from"./chunks/framework.Ai2o9gNv.js";const o="/assets/image-20260413154045626.V2TwsWCi.png",p="/assets/image-20260413154541735.BfwJG0SO.png",r="/assets/image-20260413154225316.DGxbayAP.png",i="/assets/image-20260413154602023.BnsNKvgc.png",c="/assets/image-20260413154813074.BOHEdyT1.png",l="/assets/image-20260413154858988.iHi-1JdT.png",g="/assets/image-20260319112129047.DwsjRa7j.png",m="/assets/image-20260319112141353.BEgtRErq.png",h="/assets/image-20260319112213191.M77Hy72a.png",d="/assets/image-20260319112225263.CinJpEM3.png",u="/assets/image-20260413155906343.DlU42Oiu.png",_="/assets/image-20260413155934189.BHN8iSGs.png",b="/assets/image-20260413155955375.P6pQD1F1.png",q="/assets/image-20260413160559743.D00leyum.png",w="/assets/image-20260413160708077.BQaIFPk2.png",k="/assets/image-20260413161037246.kZ6nO7p0.png",C=JSON.parse('{"title":"码道（codeArts） 解决openclaw ⽣成⼩说的质量  支持免费使用GLM5.1","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/码道 助我高效开发 小说质量优化插件/码道 解决openclaw ⽣成⼩说的质量.md","filePath":"AI人工智能/码道 助我高效开发 小说质量优化插件/码道 解决openclaw ⽣成⼩说的质量.md","lastUpdated":1776068309000,"__rawMarkdown":"# 码道（codeArts） 解决openclaw ⽣成⼩说的质量  支持免费使用GLM5.1\\n\\n## 背景\\n\\n​\\t最近的openclaw小龙虾特别火，那么万少也是使用了小龙虾来玩一些有意思的功能。其中呢，我用它来帮我生成小说，以及自动发布小说到小说平台上。\\n\\n​\\t然后，当万少把小说发布到七猫小说平台上的时候，发现这个平台有一个挺有意思的功能，就是它会用AI帮我检查我当前小说的质量，如它可以检测出来，这一章小说它的剧情有点太拖沓了，或者是剧情有点冗余了。它可以呢，简单的帮我检查出来。\\n\\n​\\t那这个时候，我们就想要去修改这一篇小说，那一般的场景是，我们只能回到本地文件中来修改这个小说。考虑到用户的注意力需要从浏览器又切换回本地，那这个过程体验起来不太好，如果我们可以直接在七猫小说的平台上直接一键优化，那能达到这个能力就太好了。\\n\\n​\\t所以基于这个需求呢，我就使用码道开发了一款谷歌浏览器插件，这个浏览器插件呢，就可以检测我们七猫小说的这个文本，然后提供了众多的优化方案，如有这个检查冗于扩写错别字、剧情等等等等。\\n\\n​\\t接下来呢，我们就分享一下这个插件是怎么样通过码道来生成的。\\n\\n## 什么是码道 （CodeArts）\\n\\n> ​\\t一个由华为云主导开发、一个理解项目需求，懂得编码之道，善用百器的实干派AI研发专家\\n\\n![](assets/image-20260413154045626.png)\\n\\n## 注册华为云账号\\n\\n> https://www.huaweicloud.com/\\n\\n使用码道需要用到华为云账号，这里可以先注册好。\\n\\n目前码道也支持免费使用 **GLM5.1**，值得一试。\\n\\n> 如果使用人数太多的话，建议选择 GLM5.0模型或者4.7模型。\\n\\n![](assets/image-20260413154541735.png)\\n\\n\\n\\n## 下载和安装\\n\\n> https://codearts.huaweicloud.com/?source=dmzntsq1&sourcead=gw\\n\\n​\\t打开码道的官网，根据自己的操作系统来下载和安装\\n\\n![](assets/image-20260413154225316.png)\\n\\n## 然后在桌面上打开码道\\n\\n![](assets/image-20260413154602023.png)\\n\\n> 你可以创建一个文件夹用来存放你的工程。\\n\\n然后在码道上登录华为云账号。\\n\\n![](assets/image-20260413154813074.png)\\n\\n## 选择开发范式\\n\\n![](assets/image-20260413154858988.png)\\n\\n你可以选择**探索模式**和**规范驱动模式**或者直接开始开发。\\n\\n​\\t如果你是使用码道从0到1开发项，那么建议使用 **规范驱动模式**的方式，它会先帮你生成需求文档、验收文档，然后待你审核通过了，再开始编码。一口气基本可以做到把工程写得七七八八。\\n\\n​\\t如果你是用码道开发已有的工程，那么你可以选择**探索模式**，边聊天边开发。\\n\\n万少这里是选择了**规范驱动模式**，因为我希望码道一口气帮我完成整个工程。\\n\\n## 开始输入需求\\n\\n```\\n帮我创建一个谷歌浏览器插件，它的功能是可以将我鼠标选中的部分文本内客，进行重构。这个重构主要是针对七猫小说平台审核我的文章的。它有会在需要调整的地方添加黄色标记。我现在想要了解，这个插件如何设计才可以做到，一键将小说内容进行调整 (主要是移除重复情节)\\n```\\n\\n![](assets/image-20260319112129047.png)\\n\\n## 生成需求规格文档\\n\\n接着码道自己开始帮我生成这个工程的需求规格文档。\\n\\n![](assets/image-20260319112141353.png)\\n\\n## 开发者自己审核\\n\\n这个时候，开发者可以自己审核这个文档，进行必要的调整。然后告知码道，可以继续下一步。\\n\\n\\n\\n## 项目开发完成\\n\\n码道会根据已有的文档制定开发计划，然后一口气帮我们把工程开发完，这个时候我的目录下便得到了谷歌浏览器插件的产物。\\n\\n![](assets/image-20260319112213191.png)\\n\\n---\\n\\n![](assets/image-20260319112225263.png)\\n\\n## 谷歌浏览器加载插件\\n\\n此时可以在谷歌浏览器上加载这个插件来验证功能。\\n\\n![](assets/image-20260413155906343.png)\\n\\n---\\n\\n勾选开发者选项。\\n\\n![](assets/image-20260413155934189.png)\\n\\n---\\n\\n选择开发好的浏览器插件\\n\\n![](assets/image-20260413155955375.png)\\n\\n---\\n\\n成功加载\\n\\n![](assets/image-20260413160559743.png)\\n\\n## 配置插件\\n\\n插件想要实现优化文本的功能，其实也是需要用到AI能力的，所以在开发的时候，我也添加了插件中添加兼容openAI大模型的配置。允许用户自己填写自己的模型配置。\\n\\n![](assets/image-20260413160708077.png)\\n\\n## 执行优化小说\\n\\n在网页上需要调整的小说部分，选中需要优化的文本，右键，然后可以自助的选择菜单，便可完成这个小说的优化了。\\n\\n\\n\\n![](assets/image-20260413161037246.png)\\n\\n## 关于我\\n\\n\\n\\n万少-万绍业\\n\\n华为HDE · 鸿蒙极客 · 全栈工程师\\n\\n10年互联网从业经验，资深全栈工程师，前端开源生态贡献者。具有丰富vue、react、小程序、鸿蒙原生应用开发经验。 鸿蒙三方库-ef-tool贡献者"}'),f={name:"AI人工智能/码道 助我高效开发 小说质量优化插件/码道 解决openclaw ⽣成⼩说的质量.md"};function A(P,a,x,I,v,G){return e(),s("div",null,[...a[0]||(a[0]=[t("",66)])])}const D=n(f,[["render",A]]);export{C as __pageData,D as default};
